#!/bin/sh
# Init script for Yandex Music provider Docker dev environment.
# Auto-generated by ma-provider-tools — do not edit manually.
set -e

echo "==> Setting up Yandex Music provider..."
# Locate MA providers directory inside the container venv
PROVIDERS_DIR=$(/app/venv/bin/python3 -c \
    "import music_assistant.providers, os; print(os.path.dirname(music_assistant.providers.__file__))")

# Remove any existing provider (image may bundle one), then symlink ours
rm -rf "${PROVIDERS_DIR}/yandex_music"
ln -s /tmp/provider "${PROVIDERS_DIR}/yandex_music"
echo "==> Provider linked: ${PROVIDERS_DIR}/yandex_music"

# Install the same provider-specific runtime dependencies as the MA loader.
DEPS=$(/app/venv/bin/python3 - /tmp/provider/manifest.json <<'PYEOF'
import json
import sys

with open(sys.argv[1], encoding="utf-8") as manifest_file:
    manifest = json.load(manifest_file)
print("\n".join(manifest.get("requirements", [])))
PYEOF
)
if [ -n "$DEPS" ]; then
    echo "==> Installing provider dependencies: $DEPS"
    # The official ghcr.io/music-assistant/server image ships uv but no pip
    # in the venv, so the bare `pip install` path crashes on
    # `/app/venv/bin/pip: not found`. Prefer uv when available; fall back
    # to pip for any image that still has it.
    if [ -x /app/venv/bin/uv ]; then
        printf '%s\n' "$DEPS" | /app/venv/bin/uv pip install --quiet --index-strategy unsafe-best-match --python /app/venv/bin/python -r -
    else
        printf '%s\n' "$DEPS" | /app/venv/bin/pip install --quiet -r -
    fi
fi

echo "==> Starting Music Assistant..."
exec /usr/local/bin/entrypoint.sh --data-dir /data --cache-dir /data/.cache
